#include <iostream>
#include <vector>
#include <algorithm>
#include <iterator>

using namespace std;

using lint = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    lint n;
    cin >> n;
    vector<lint> a(n);
    copy_n(istream_iterator<lint>(cin), n, a.begin());

    lint k;
    cin >> k;

    sort(a.begin(), a.end());

    lint max_count = 1;
    for (lint i = 0; i < n; ++i) {
        lint count = 1;
        lint j = i + 1;
        while (j < n && a[j] - a[i] <= k) {
            ++count;
            ++j;
        }
        max_count = max(max_count, count);
    }

    cout << max_count << '\n';
    return 0;
}
